mapper.select:
select count(*)
from b_zhongan_colliding_data_log
where  report_date >= DATE_SUB(#{bizDate,jdbcType=VARCHAR}, INTERVAL 1 DAY)
  and report_date <= #{bizDate,jdbcType=VARCHAR} 
  and sms_send_status = 1
  and cell = #{cellMd5,jdbcType=VARCHAR}

select count(*)
from b_zhongan_colliding_data_log
where  report_date >= DATE_SUB(#{bizDate,jdbcType=VARCHAR}, INTERVAL 2 DAY)
  and report_date <= #{bizDate,jdbcType=VARCHAR} 
  and is_connect = 1
  and cell = #{cellMd5,jdbcType=VARCHAR}
